import re

def parse_demo(msg_text, n):
    m=re.search(rf'Demo pair {n} input \(28x28\):\n(.*?)\nDemo pair {n} output \(28x28\):\n(.*?)(?:\n\nSame instance\.|$)', msg_text, re.S)
    if not m:
        raise ValueError(f'could not parse demo {n}')
    parse=lambda s:[[int(x) for x in line.split()] for line in s.strip().splitlines()]
    a,b=parse(m.group(1)),parse(m.group(2))
    return a,b
